CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_alerta_contexto` AS
select `s`.`id_alert` AS `id_alert`,`s`.`inicio` AS `inicio`,round(((unix_timestamp() - `s`.`inicio_epoch`) / 3600),1) AS `horas_abierta`,`s`.`severidad` AS `severidad`,`s`.`texto` AS `texto`,substring_index(substring_index(`s`.`event_data`,'**ALERT',-(1)),'**',1) AS `expresion`,`s`.`que_mide` AS `que_mide`,`s`.`concepto` AS `concepto`,`s`.`unidad` AS `unidad`,`s`.`clase` AS `clase`,`s`.`dispositivo` AS `dispositivo`,`s`.`ip` AS `ip`,`s`.`instancia` AS `instancia`,`s`.`rol` AS `rol`,`s`.`rol_nombre` AS `rol_nombre`,`s`.`rol_tipo` AS `rol_tipo`,`s`.`criticidad` AS `criticidad`,`s`.`es_primaria` AS `es_primaria`,(select count(0) from (((`alerts_store` `h` left join `sem_metric_binding` `hb` on(((`hb`.`idmetric` = `h`.`id_metric`) and (`hb`.`status` = 'active')))) left join `sem_instance` `hi` on((`hi`.`instance_id` = `hb`.`instance_id`))) left join `sem_metric_concept` `hc` on((`hc`.`subtype` = `hi`.`subtype`))) where ((`h`.`date` > (unix_timestamp() - 2592000)) and ((case when (coalesce(`hi`.`canonical_override`,`hc`.`canonical_id`) in ('net.icmp.latency','net.icmp.availability')) then concat('dev:',`h`.`id_device`,':icmp') else concat('inst:',`hi`.`instance_id`) end) = `s`.`senal_id`))) AS `veces_30d`,(select round((avg(`h`.`duration`) / 60),1) from (((`alerts_store` `h` left join `sem_metric_binding` `hb` on(((`hb`.`idmetric` = `h`.`id_metric`) and (`hb`.`status` = 'active')))) left join `sem_instance` `hi` on((`hi`.`instance_id` = `hb`.`instance_id`))) left join `sem_metric_concept` `hc` on((`hc`.`subtype` = `hi`.`subtype`))) where ((`h`.`date` > (unix_timestamp() - 2592000)) and (`h`.`duration` > 0) and ((case when (coalesce(`hi`.`canonical_override`,`hc`.`canonical_id`) in ('net.icmp.latency','net.icmp.availability')) then concat('dev:',`h`.`id_device`,':icmp') else concat('inst:',`hi`.`instance_id`) end) = `s`.`senal_id`))) AS `dur_media_min`,(select count(0) from `alerts` `o` where ((`o`.`id_device` = `s`.`iddev`) and (`o`.`id_alert` <> `s`.`id_alert`) and (`o`.`severity` <> 4))) AS `otras_del_equipo`,(select count(distinct `o`.`id_alert`) from ((`alerts` `o` join `sem_metric_binding` `ob` on(((`ob`.`idmetric` = `o`.`id_metric`) and (`ob`.`status` = 'active')))) join `sem_binding_role` `obr` on(((`obr`.`instance_id` = `ob`.`instance_id`) and (`obr`.`status` = 'active')))) where ((`obr`.`role_id` = `s`.`rol`) and (`o`.`id_alert` <> `s`.`id_alert`) and (`o`.`severity` <> 4))) AS `otras_del_rol`,(select group_concat(distinct `o`.`name` order by `o`.`name` ASC separator ', ') from `alerts` `o` where ((`o`.`id_alert` <> `s`.`id_alert`) and (`o`.`severity` <> 4) and (abs((`o`.`date` - `s`.`inicio_epoch`)) <= 900))) AS `simultaneas` from `v_alerta_semantica` `s`;
